result = Broker.CALCULATE(
    distinct_customers_count=COUNT(
        Customers.WHERE(
            ENDSWITH(LOWER(email), ".com") &
            HAS(transactions_made.WHERE(
                ISIN(UPPER(ticker.symbol), ("AMZN", "AAPL", "GOOGL", "META", "NFLX"))
            )) == 1
        )
    )
)

usa_transactions_last_week = Customers.WHERE(
    LOWER(country) == "usa"
).transactions_made.WHERE(
    DATEDIFF("weeks", date_time, DATETIME("now")) == 1
)

result = Broker.CALCULATE(
    num_transactions=COUNT(usa_transactions_last_week),
    total_amount=SUM(usa_transactions_last_week.amount)
)

result = Transactions.WHERE(
    (LOWER(transaction_type) == "buy") &
    (DATEDIFF("days", date_time, DATETIME("now")) <= 10)
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(name="ticker_groups", by=ticker_symbol).CALCULATE(
    ticker_symbol=ticker_symbol,
    num_buy_transactions=COUNT(Transactions)
).TOP_K(2, by=num_buy_transactions.DESC())

result = Broker.CALCULATE(
    num_customers=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

prices_in_range = historical_prices.WHERE(
    (date >= '2023-04-01') & (date <= '2023-04-04')
)
top_stocks_by_price_change = Tickers.WHERE(
    HAS(prices_in_range) == 1
).CALCULATE(
    ticker_symbol=symbol,
    price_change=MAX(prices_in_range.high) - MIN(prices_in_range.low)
).TOP_K(
    3, by=price_change.DESC()
)

top_customers = Customers.WHERE(
    HAS(transactions_made) == 1
).CALCULATE(
    customer_name=name,
    total_amount=SUM(transactions_made.amount)
).TOP_K(5, by=total_amount.DESC())

result = Customers.WHERE(
    HAS(transactions_made.WHERE(LOWER(transaction_type) == 'buy')) == 1
).CALCULATE(
    customer_id=_id
)

lowest_price_past_7_days = Broker.CALCULATE(
    lowest_close_price=MIN(DailyPrices.WHERE((LOWER(ticker.symbol) == 'vti') & (DATEDIFF("days", date, 'now') <= 7)).close)
)

result = Broker.CALCULATE(
    total_transactions=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, DATETIME('now')) <= 70
        ).transactions_made
    )
)

