    asp_q1_2023 = AVG(Sales.WHERE(
        (YEAR(sale_date) == 2023) & 
        (MONTH(sale_date) <= 3)
    ).sale_price)
)

result = Dealership.CALCULATE(
    avg_days_to_payment=ROUND(
        AVG(
            Sales.WHERE(HAS(payment)==1).payment.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ), 
        2
    )
)

gpm_2023 = Dealership.CALCULATE(
    total_revenue=SUM(Sales.WHERE(YEAR(sale_date) == 2023).sale_price),
    total_cost=SUM(Sales.WHERE(YEAR(sale_date) == 2023).car.cost),
).CALCULATE(
    gpm=(total_revenue - total_cost) / total_cost * 100
)

result = Sales.WHERE(
    HAS(car.inventory_snapshots.WHERE(
        (is_in_inventory == False) & 
        (snapshot_date == sale_date)
    )) == 1
).CALCULATE(
    car_make=car.make,
    car_model=car.model,
    sale_price=sale_price
).TOP_K(1, by=sale_price.DESC())

tsc_past_7_days = Dealership.CALCULATE(
    total_sales_count=COUNT(Sales.WHERE(DATEDIFF("days", sale_date, "now") <= 7))
)

customers_with_purchases = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id=_id
)

cash_payment_salespersons = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(LOWER(payment_method) == "cash")) == 1
).CALCULATE(salesperson_id = _id)

result = cash_payment_salespersons.PARTITION(name="unique_salespersons", by=salesperson_id).CALCULATE(
    salesperson_id = salesperson_id
)

weekend_utility_payments = Dealership.CALCULATE(
    num_weekend_utility_payments=COUNT(
        PaymentsMade.WHERE(
            (LOWER(vendor_name) == LOWER('Utility Company')) &
            ((DAYOFWEEK(payment_date) == 6) | (DAYOFWEEK(payment_date) == 7))
        )
    )
)

result = Drugs.CALCULATE(
    drug_name=drug_name,
    average_ddd=AVG(
        treatments_used_in.WHERE(PRESENT(end_dt)).CALCULATE(
            ddd=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd
    )
)

